    ('PKG-1313', 'form_a.pdf', 'yes', 'apr-1313'),
    ('PKG-1313', 'photo_a.jpg', 'yes', 'apr-1313'),
}
selected_aliases = {'yes', 'true', '1', 'selected'}
header = ['package', 'filename', 'selected', 'approval_code']
ok = False
try:
    with zipfile.ZipFile(path) as archive:
        names = archive.namelist()
        structure_ok = len(names) == 3 and len(set(names)) == 3 and set(names) == expected_names and all('/' not in name for name in names)
