        index_ok = False
        if structure_ok:
            reader = csv.DictReader(io.StringIO(archive.read('evidence_index.csv').decode('utf-8-sig')))
            rows = list(reader)
            rows_well_formed = all(set(row) == set(header) and all(value is not None for value in row.values()) for row in rows)
            actual_rows = {
                (
                    row.get('package', '').strip(),
                    row.get('filename', '').strip().casefold(),
                    'yes' if row.get('selected', '').strip().casefold() in selected_aliases else None,
                    row.get('approval_code', '').strip().casefold(),
                )
                for row in rows
            }
            index_ok = reader.fieldnames == header and len(rows) == 2 and rows_well_formed and len(actual_rows) == 2 and actual_rows == expected_rows
        ok = structure_ok and hashes_ok and index_ok
except Exception:
    ok = False
print('pass' if ok else 'fail')
